import 'package:flutter/foundation.dart';

import '../../image_picker_platform_interface.dart';

/// A recent item from the device's media library, as returned by
/// [ImagePickerPlatform.getRecentMedia].
@immutable
class RecentMedia {
  /// Creates a new RecentMedia instance.
  const RecentMedia({required this.thumbnail, required this.type});

  /// A JPEG thumbnail of the item, generated by the operating system.
  ///
  /// This is always an image, even when [type] is [MediaSelectionType.video].
  final XFile thumbnail;

  /// The type of the original item.
  final MediaSelectionType type;
}
